def signal(obs):
    # ultra conservative cross arb only, test if any diffusion threshold profitable
    res={}
    for a,b,thr,scale in [('A','A.X',8,2),('B','B.X',4,2),('C','C.X',6,2)]:
        ma=obs.last(a,'mid'); mb=obs.last(b,'mid')
        if np.isnan(ma) or np.isnan(mb):
            continue
        diff=ma-mb
        if abs(diff) < thr:
            res[a]=0.0
            res[b]=0.0
        else:
            # estimate expected reversion 50 steps slope ~ -0.4 to -0.6 => expected move ~ -slope*diff ~0.4*diff ~ 3-4 cents for 8 diff => less than spread
            # need bigger diff to overcome spread+fee ~ half spread 5 + fee 3 =8
            sig = -diff / 10.0
            sig = max(-1,min(1,sig))
            res[a]=float(sig)
            res[b]=float(-sig)
    return res

def signal(obs):
    # Try imbalance signal with threshold, maybe not paying spread if we trade slow?
    res={}
    for a in ['A','B','C','IDX']:
        imb = obs.last(a,'imbalance')
        if np.isnan(imb):
            continue
        # corr ~0.2 for 10-step, predicted move ~ corr*std*imb?
        # std ret10 ~2-3 cents, imb moves 1 stdev ~? imb std maybe 0.3?
        # predicted move ~0.2*2*imb ~0.4*imb cents ~0.4 cents for imb=1 => tiny vs spread 10c
        # So imbalance alone can't overcome spread with market orders.
        # Let's test with huge threshold like |imb|>0.6 and small size, see pnl
        if abs(imb) < 0.6:
            res[a]=0.0
        else:
            sig = np.clip(imb*0.8, -1,1)
            res[a]=float(sig)
    return res

