def signal(obs):
    mI = obs.last('IDX','mid')
    mA = obs.last('A','mid')
    mB = obs.last('B','mid')
    mC = obs.last('C','mid')
    if mI is None or mA is None or mB is None or mC is None:
        return {}
    # handle NaN
    try:
        import math
        if math.isnan(mI) or math.isnan(mA) or math.isnan(mB) or math.isnan(mC):
            return {}
    except: pass
    syn = 0.3333*mA + 0.6667*mB + 0.1667*mC
    basis = mI - syn
    # threshold in cents
    thr = 4.0
    if basis > thr:
        # IDX rich: short IDX, long basket
        return {'IDX': -1.0, 'A': 0.3333, 'B': 0.6667, 'C': 0.1667}
    elif basis < -thr:
        return {'IDX': 1.0, 'A': -0.3333, 'B': -0.6667, 'C': -0.1667}
    else:
        return {'IDX': 0.0, 'A': 0.0, 'B': 0.0, 'C': 0.0}

