def signal(obs):
    # IDX vs basket reversion: trade IDX only (single leg)
    a = obs.last('A', 'mid'); b = obs.last('B', 'mid'); c = obs.last('C', 'mid'); i = obs.last('IDX', 'mid')
    if a!=a or b!=b or c!=c or i!=i:
        return {}
