def signal(obs):
    st = obs.state
    out = {}
    for s in ['A', 'B', 'C']:
        a = obs.last(s, 'mid'); b = obs.last(s + '.X', 'mid')
        if a != a or b != b:
            continue
        gap = b - a
        prev = st.get(s, 0.0)
        # deadband: enter only if |gap|>6, exit when |gap|<1
        if prev == 0.0:
            if gap > 6: prev = 1.0
            elif gap < -6: prev = -1.0
            else: prev = 0.0
        elif prev > 0:
            if gap < 1: prev = 0.0
            else: prev = 1.0
        else:
            if gap > -1: prev = 0.0
            else: prev = -1.0
        st[s] = prev
        out[s] = prev
    return out

