def signal(obs):
    # C 200-step momentum, slow, low turnover
    st = obs.state
    h = obs.hist('C', 'mid', 250)
    # h oldest first, last is latest
    if len(h) < 210 or h[-1] != h[-1] or h[-200] != h[-200]:
        return {}
    past = h[-1] - h[-200]
    # deadband to reduce turnover
    prev = st.get('p', 0.0)
    if prev == 0.0:
        if past < -8: prev = -1.0
        elif past > 8: prev = 1.0
    elif prev < 0:
        if past > 0: prev = 0.0
    else:
        if past < 0: prev = 0.0
    st['p'] = prev
    return {'C': prev}

