def signal(obs):
    targets = {}
    for asset in ['A','B','C']:
        m = obs.hist(asset, 'mid', 60)
        if m is None or len(m)<55:
            continue
        cur = m[-1]
        prev = m[-51] if len(m)>=51 else m[0]
        m20 = m[-21] if len(m)>=21 else prev
        # check NaN via not equal self
        if cur!=cur or prev!=prev or m20!=m20:
            continue
        if prev==0 or m20==0:
            continue
        ret50 = (cur - prev)/prev
        ret20 = (cur - m20)/m20
        if asset=='C':
            sig = ret50*100 + ret20*50
        elif asset=='B':
            sig = ret50*80 + ret20*40
        else:
            sig = ret50*30 + ret20*30
        val = sig*5
        if val>1:
            val=1
        if val<-1:
            val=-1
        if abs(val)<0.1:
            val=0
        targets[asset]=val
    return targets

def signal(obs):
    out = {}
    # helper to compute vol quickly
    for asset in ['A','B','C']:
        m = obs.hist(asset, 'mid', 70)
        if m is None or len(m) < 61:
            continue
        cur = m[-1]
        v21 = m[-21]
        v61 = m[-61]
        if cur!=cur or v21!=v21 or v61!=v61:
            continue
        trail20 = cur - v21
        drift = (cur - v61)/60*20
        excess = trail20 - drift
        # vol estimate mean absolute 1-step
        vol = 0
        cnt = 0
        for i in range(-60, -1):
            a = m[i+1]
            b = m[i]
            if a==a and b==b:
                d = a-b
                if d<0:
                    d = -d
                vol += d
                cnt += 1
        if cnt>0:
            vol = vol/cnt
        else:
            vol = 1.5
        if vol < 0.5:
            vol = 0.5
        z = excess / (vol*4.5)
        imb_arr = obs.hist(asset, 'imbalance', 5)
        imb = 0
        if imb_arr is not None and len(imb_arr)>0:
            imb = imb_arr[-1]
            if imb!=imb:
                imb=0
        # weights: for C momentum stronger
        if asset == 'C':
            sig = 0.75*z + 0.25*imb*1.2
        elif asset == 'B':
            sig = 0.6*z + 0.4*imb*1.4
        else:
            sig = 0.55*z + 0.45*imb*1.0
        if sig > 1.5:
            sig = 1.5
        if sig < -1.5:
            sig = -1.5
        sig = sig/1.5
        if abs(sig) < 0.15:
            sig = 0
        prev = obs.state.get(asset, 0)
        # EMA smoothing to reduce turnover
        if asset == 'C':
            alpha = 0.4
        elif asset == 'B':
            alpha = 0.4
        else:
            alpha = 0.35
        smoothed = (1-alpha)*prev + alpha*sig
        if smoothed > 1:
            smoothed = 1
        if smoothed < -1:
            smoothed = -1
        # small dead zone after smoothing
        if abs(smoothed) < 0.05:
            smoothed = 0
        obs.state[asset] = smoothed
        out[asset] = smoothed

    # IDX imbalance only (momentum weak)
    imb_arr = obs.hist('IDX', 'imbalance', 5)
    m = obs.hist('IDX', 'mid', 30)
    if imb_arr is not None and m is not None and len(imb_arr)>0 and len(m)>=10:
        imb = imb_arr[-1]
        if imb==imb:
            sig = imb*1.0
            if sig > 1:
                sig = 1
            if sig < -1:
                sig = -1
            if abs(sig) < 0.18:
                sig = 0
            prev = obs.state.get('IDX', 0)
            smoothed = 0.5*prev + 0.5*sig
            if smoothed>1:
                smoothed=1
            if smoothed<-1:
                smoothed=-1
            if abs(smoothed)<0.05:
                smoothed=0
            obs.state['IDX']=smoothed
            out['IDX']=smoothed

    # explicitly keep X venues flat to avoid 3bps fees
    out['A.X']=0
    out['B.X']=0
    out['C.X']=0
    return out

