            if sig > 1:
                sig = 1
            if sig < -1:
                sig = -1
            if abs(sig) < 0.18:
                sig = 0
            prev = obs.state.get('IDX', 0)
            smoothed = 0.5*prev + 0.5*sig
            if smoothed>1:
