# imbalance and signed volume predictiveness: corr with future 10,50 step returns
for a in ['A','B','C','IDX']:
    mid=f(H[a]['mid']); imb=f(H[a]['imbalance']); sv=f(H[a]['signed_volume'])
    for feat,fn in [('imb',imb),('sv',sv)]:
        for h in [10,50]:
            fut=mid[h:]-mid[:-h]
            past=fn[:-h]
            m=np.isfinite(fut)&np.isfinite(past)
            c=float(np.corrcoef(past[m],fut[m])[0,1]) if m.sum()>200 else float('nan')
            result[a+'_'+feat+'_f'+str(h)]=round(c,4)
# cross: does B predict A? etc lead-lag 10 steps
mids={a:f(H[a]['mid']) for a in ['A','B','C','IDX']}
for a in ['A','B','C']:
    for b in ['IDX']:
        ra=mids[a][10:]-mids[a][:-10]
        rb=mids[b][10:]-mids[b][:-10]
        # corr ra[t] with rb[t+10] (a leads b)
        x=ra[:-10]; y=rb[10:]
        m=np.isfinite(x)&np.isfinite(y)
        c=float(np.corrcoef(x[m],y[m])[0,1]) if m.sum()>200 else float('nan')
        result[a+'_leads_'+b]=round(c,4)
        x2=rb[:-10]; y2=ra[10:]
        m2=np.isfinite(x2)&np.isfinite(y2)
        c2=float(np.corrcoef(x2[m2],y2[m2])[0,1]) if m2.sum()>200 else float('nan')
        result[b+'_leads_'+a]=round(c2,4)

