def corr(a,b):
    m=np.isfinite(a)&np.isfinite(b)
    if np.sum(m)<50:
        return float('nan')
    a=a[m]; b=b[m]
    am=a.mean(); bm=b.mean()
    denom=math.sqrt(((a-am)**2).sum()*((b-bm)**2).sum())
    if denom==0:
        return float('nan')
    return float(((a-am)*(b-bm)).sum()/denom)
def slope(a,b):
    m=np.isfinite(a)&np.isfinite(b)
    if np.sum(m)<50:
        return float('nan')
    a=a[m]; b=b[m]
    am=a.mean(); bm=b.mean()
    var_a = ((a-am)**2).sum()
    if var_a==0:
        return float('nan')
    return float(((a-am)*(b-bm)).sum()/var_a)

