def ic(asset, lag):
    m = H[asset]['mid']
    fwd = np.full(len(m), np.nan)
    fwd[:-50] = m[50:] - m[:-50]
    sig = np.full(len(m), np.nan)
    sig[lag:] = m[lag:] - m[:-lag]
    valid = ~(np.isnan(sig) | np.isnan(fwd))
    if np.sum(valid) < 100:
        return float('nan')
    return float(np.corrcoef(sig[valid], fwd[valid])[0,1])

