# check risk-adjusted net: A/B gross maybe 1.1 per step vs C 6 . After costs, A/B likely negative due to spread 10c turnover ~0.1 => cost 1c per step?
# Let's estimate turnover cost more precisely via simulation proxy on visible history

def simulate(asset, thr, scale, lag=50):
    m = H[asset]['mid']
    spread = H[asset]['spread']
    # simple backtest: target t as defined, execution lag 10 steps? actual engine trades toward target at 2 lots per step => delay
    # approximate: we rebalance every 10 steps, cost = abs(delta_t)*15 * spread/2 ?
    # gross pnl per step = t_prev * (m[t]-m[t-1])
    # Let's simulate every 10 steps signal
    t_prev = 0.0
    pnl = 0.0
    costs = 0.0
    turns = 0.0
    for i in range(55, len(m)-1):
        if i % 10 != 0:
            # hold position
            pass
        else:
            # compute signal at i
            if np.isnan(m[i]) or np.isnan(m[i-lag]):
                sig = 0
            else:
                sig = m[i] - m[i-lag]
            if sig > thr:
                t = np.clip((sig - thr)/scale,0,1)
            elif sig < -thr:
                t = np.clip((sig + thr)/scale,-1,0)
            else:
                t = 0.0
            # cost to change position
            delta = abs(t - t_prev)
            avg_spread = spread[i] if not np.isnan(spread[i]) else 10
            costs += delta * 15 * avg_spread/2  # paying half spread per lot? actually market order pays half spread per lot
            turns += delta
            t_prev = t
        # pnl from price move with current t_prev
        if not np.isnan(m[i+1]) and not np.isnan(m[i]):
            pnl += t_prev * 15 * (m[i+1]-m[i])
    net = pnl - costs
    return (pnl, costs, net, turns)

