      c+=1; sx+=a; sy+=b; sxy+=a*b; sxx+=a*a; syy+=b*b
  if c<10: return (float('nan'),0)
  mx=sx/c; my=sy/c
  cov=sxy/c-mx*my; vx=sxx/c-mx*mx; vy=syy/c-my*my
