def ic(asset, lag, horizon=50):
    m = H[asset]['mid']
    n = len(m)
    # compute past lag return and future horizon return
    # ensure valid
    past = m[lag: n-horizon] - m[0: n-horizon-lag]
    fut = m[lag+horizon: n] - m[lag: n-horizon]
    # mask nans
    mask = ~(np.isnan(past) | np.isnan(fut))
    past = past[mask]; fut = fut[mask]
    if len(past)<100:
        return float('nan')
    # spearman approximation via pearson on rank? simple pearson
    c = np.corrcoef(past, fut)[0,1]
    return float(c)

