import math
def corr(a,b):
    m = np.isfinite(a) & np.isfinite(b)
    if np.sum(m) < 500:
        return float('nan')
    a=a[m]; b=b[m]
    am=np.mean(a); bm=np.mean(b)
    num=np.sum((a-am)*(b-bm))
    den=math.sqrt(np.sum((a-am)**2)*np.sum((b-bm)**2))
    return float(num/den) if den!=0 else float('nan')

Hmid = {k: H[k]['mid'] for k in ['A','B','C','IDX','A.X','B.X','C.X']}
n=len(Hmid['A'])
res={}
for asset in ['A','B','C','IDX','A.X','B.X','C.X']:
    m=Hmid[asset]
    rs={}
    for lag in [10,30,50,80,120]:
        # past return lag steps: m[t]-m[t-lag]
        # future return 50 steps: m[t+50]-m[t]
        if n < lag+60:
            rs[lag]=float('nan')
            continue
        past = m[lag:-50] - m[:-lag-50]  # length n-lag-50
        # need align: past at t, future at t: m[t+50]-m[t]
        fut = m[lag+50:] - m[lag:-50]
        # both same length n-lag-50
        c = corr(past, fut)
        rs[lag]=round(float(c),4)
    res[asset]=rs

