def corr(a,b):
    m=np.isfinite(a)&np.isfinite(b)
    if np.sum(m)<200:
        return float('nan')
    a=a[m]; b=b[m]
    am=np.mean(a); bm=np.mean(b)
    den=math.sqrt(np.sum((a-am)**2)*np.sum((b-bm)**2))
    return float(np.sum((a-am)*(b-bm))/den) if den!=0 else float('nan')

