def ic(asset, lag, horizon=50):
    a = H[asset]['mid']
    n = len(a)
    sig = []
    fwd = []
    for t in range(lag, n-horizon):
        if np.isnan(a[t]) or np.isnan(a[t-lag]) or np.isnan(a[t+horizon]):
            continue
        s = a[t]-a[t-lag]
        f = a[t+horizon]-a[t]
        sig.append(s)
        fwd.append(f)
    if len(sig)<100:
        return float('nan')
    sig = np.array(sig)
    fwd = np.array(fwd)
    c = np.corrcoef(sig, fwd)[0,1]
    return float(c)

