def sim2(asset, lag, thr, scale, fee_bps):
    mid=H[asset]['mid']
    spread=H[asset]['spread']
    n=len(mid)
    gross=0.0
    cost=0.0
    pos=0.0
    for t in range(lag, n-1):
        if np.isnan(mid[t]) or np.isnan(mid[t-lag]):
            target=0.0
        else:
            diff=mid[t]-mid[t-lag]
            if diff>thr:
                v=(diff-thr)/scale
                if v>1: v=1
                target=v
            elif diff< -thr:
                v=(diff+thr)/scale
                if v<-1: v=-1
                target=v
            else:
                target=0.0
        delta=target-pos
        spr= spread[t]/2 if not np.isnan(spread[t]) else 6
        fee= fee_bps/10000 * mid[t] if not np.isnan(mid[t]) else 0  # approx per lot per trade? fee on notional traded
        # fee applies to taker volume traded: delta lots * price * bps
        # our pos unit is normalized 1 = 15 lots, so cost scales but ratio same
        cost += abs(delta)*(spr+fee)
        if not np.isnan(mid[t+1]) and not np.isnan(mid[t]):
            move=mid[t+1]-mid[t]
        else:
            move=0
        gross+= pos*move
        pos=target
    net=gross-cost
    return float(gross), float(net), float(cost)

