assets = ['A','B','C','IDX','A.X','B.X','C.X']

def ic(asset, lag, horizon=50):
    mid = H[asset]['mid']
    n = len(mid)
    sig = mid[lag: n-horizon] - mid[: n-horizon-lag]
    ret = mid[lag+horizon: n] - mid[lag: n-horizon]
    mask = ~(np.isnan(sig) | np.isnan(ret))
    s = sig[mask]
    r = ret[mask]
    if len(s) < 100:
        return float('nan')
    c = np.corrcoef(s, r)[0,1]
    return float(c)

results={}
for lag in [5,10,20,30,50,80,100]:
    for asset in ['A','B','C']:
        results[asset + "_lag"+str(lag)+"_h50"] = round(ic(asset, lag, 50),3)

for h in [10,30,50,100]:
    results["C_lag30_h"+str(h)] = round(ic('C',30,h),3)
    results["B_lag50_h"+str(h)] = round(ic('B',50,h),3)

def ic_split(asset, lag, horizon=50):
    mid = H[asset]['mid']
    n=len(mid)
    half=n//2
    def comp(m):
        nn=len(m)
        sig=m[lag: nn-horizon] - m[: nn-horizon-lag]
        ret=m[lag+horizon: nn] - m[lag: nn-horizon]
        mask=~(np.isnan(sig)|np.isnan(ret))
        s=sig[mask]; r=ret[mask]
        if len(s)<100:
            return float('nan')
        return float(np.corrcoef(s, r)[0,1])
    return comp(mid[:half]), comp(mid[half:])

for asset,lag in [('C',30),('B',50),('A',50)]:
    e,l=ic_split(asset,lag,50)
    results["split_"+asset+str(lag)+"_early"] = round(e,3)
    results["split_"+asset+str(lag)+"_late"] = round(l,3)

# also check reversal IC for IDX maybe misinterpreted? Let's compute negative lag correlation for mean reversion horizon 10
def rev_ic(asset, lag, horizon=10):
    mid = H[asset]['mid']
    n=len(mid)
    sig = -(mid[lag: n-horizon] - mid[: n-horizon-lag])
    ret = mid[lag+horizon: n] - mid[lag: n-horizon]
    mask=~(np.isnan(sig)|np.isnan(ret))
    s=sig[mask]; r=ret[mask]
    return float(np.corrcoef(s,r)[0,1])

for lag in [5,10,20,50]:
    results["IDX_rev_lag"+str(lag)+"_h10"] = round(rev_ic('IDX', lag, 10),3)
    results["C_rev_lag"+str(lag)+"_h10"] = round(rev_ic('C', lag, 10),3)
    results["A_rev_lag"+str(lag)+"_h10"] = round(rev_ic('A', lag, 10),3)

